def test_grid_from_X_ignores_nan(grid_resolution, container, feature_values, is_categorical):
    # Missing values must affect neither the unique-value count nor quantiles.
    X = feature_values.reshape(-1, 1)
    X_missing = np.concatenate([X, [[np.nan], [np.nan]]])
    if container == "dataframe":
        pd = pytest.importorskip("pandas")
        X = pd.DataFrame(X)
        X_missing = pd.DataFrame(X_missing)

    expected_axis = feature_values
    if not is_categorical and grid_resolution == 5:
        # mquantiles uses different interpolation from numpy's default.
        expected_axis = np.linspace(1.44, 7.56, grid_resolution)

    for data in (X, X_missing):
        grid, axes = _grid_from_X(
            data, (0.2, 0.8), [is_categorical], grid_resolution
        )
        if feature_values.dtype.kind == "O":
            assert_array_equal(axes[0], expected_axis)
            assert_array_equal(grid[:, 0], expected_axis)
        else:
            assert_allclose(axes[0], expected_axis)
            assert_allclose(grid[:, 0], expected_axis)


