@pytest.mark.parametrize("method", ["brute", "recursion"])
@pytest.mark.parametrize("is_categorical", [False, True])
@pytest.mark.parametrize("grid_resolution", [5, 20])
def test_partial_dependence_ignores_nan(method, is_categorical, grid_resolution):
    X = np.tile(np.arange(10, dtype=float), 10).reshape(-1, 1)
    y = np.sin(X[:, 0])
    X[::7, 0] = np.nan
    estimator = HistGradientBoostingRegressor(
        categorical_features=[is_categorical],
        min_samples_leaf=2,
        max_iter=5,
        random_state=0,
    ).fit(X, y)

    params = dict(
        features=[0],
        categorical_features=[is_categorical],
        method=method,
        grid_resolution=grid_resolution,
    )
    result = partial_dependence(estimator, X, **params)
    expected = partial_dependence(estimator, X[~np.isnan(X[:, 0])], **params)

    assert_allclose(result["grid_values"][0], expected["grid_values"][0])
    # With a single feature, all input values are replaced by grid values.
    assert_allclose(result["average"], expected["average"])


